                # If the process ended with a non-zero exit code but wasn't terminated by timeout
                if result["message"] is None:
                    result["message"] = "Script executed successfully."
        except Exception as e:
            result["message"] = f"Error: {str(e)}"

    thread = threading.Thread(target=run_script)
    thread.daemon = True
    thread.start()
    thread.join(timeout)

    if thread.is_alive():
        # Timeout occurred, terminate the process
        result["message"] = "Terminating process due to timeout."

