    """
    Executes an R script and verifies if the output file is generated within a given duration.

    Parameters:
    r_script_path (str): Path to the R script file
    output_path (str): Path to the expected output file (can include glob patterns)
    duration (int): Maximum time in seconds to wait for the file to be generated

    Returns:
    tuple: (bool, str) - Success status and message
    """
    # Check if the output file already exists before execution
    initial_files = set(glob.glob(output_path))

    # Start the R script execution
    try:
        process = subprocess.Popen(
            ['Rscript', r_script_path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
    except FileNotFoundError:
        return (False, "Rscript not found. Please ensure R is installed and in PATH.")
    except Exception as e:
        return (False, f"Failed to start R script: {str(e)}")

    # Wait for the specified duration, checking periodically
    start_time = time.time()
    while time.time() - start_time < duration:
        # Check if process has finished
        return_code = process.poll()
        if return_code is not None:
            # Process has finished, check for output files
            current_files = set(glob.glob(output_path))
            if current_files - initial_files:
                return (True, "File generated successfully within the specified duration.")
            else:
                # Get error output if any
                _, stderr = process.communicate()
                error_msg = stderr.decode('utf-8', errors='replace') if stderr else "No error output"
                return (False, f"File not generated within the specified duration. R script exited with code {return_code}. Error: {error_msg}")

        # Wait a bit before checking again
