    # Time exceeded, check if file exists anyway
    current_files = set(glob.glob(output_path))
    if current_files - initial_files:
        return (True, "File generated successfully within the specified duration.")

    # Kill the process if it's still running
    process.terminate()
    try:
        process.wait(timeout=5)
    except subprocess.TimeoutExpired:
        process.kill()

    return (False, "File not generated within the specified duration.")
